import{_ as s,l,o as e,c as i,v as t,p as n,x as o,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SSH 协议","description":"","frontmatter":{"title":"SSH 协议","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssh-protocol.md","filePath":"cs/ssh-protocol.md","lastUpdated":1789023840000}'),S={name:"cs/ssh-protocol.md"};function c(T,a,P,_,m,u){const r=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="ssh-协议" tabindex="-1">SSH 协议 <a class="header-anchor" href="#ssh-协议" aria-label="Permalink to &quot;SSH 协议&quot;">​</a></h1><div class="epigraph"><p>SSH 在一条 TCP 上先密钥交换再开信道：会话、端口转发、SFTP 都是信道类型，不是三个端口三个协议。</p><footer>—— 据 RFC 4253 SSH 运输；RFC 4254 连接协议整理</footer></div><p><a href="/cs/http-tls-entry">TLS 入口</a> 保护 HTTP。<a href="/cs/spf-dkim-dmarc">上一课</a> 是邮件。缺口是<strong>交互登录与隧道的 SSH</strong>：版本交换、KEX、认证、多信道。本课不把 NTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>telnet 明文。SSH：二进制包，运输层加密完整性，然后用户认证（公钥/密码），再 multiplex 信道。端口转发把其它应用塞进这条管道，像应用层 GRE。与 QUIC 对照：都有加密+多流，SSH 更老、跑 TCP，有 TCP HOL。主机密钥钉防中间人，类似证书钉但常 TOFU。</p><p>不要把 ssh 命令行选项当协议规范。</p><p><span class="marginnote">RFC 4251–4254。本课不写爆破密码的操作。</span></p><h3 id="加密运输加多信道" tabindex="-1">加密运输加多信道 <a class="header-anchor" href="#加密运输加多信道" aria-label="Permalink to &quot;加密运输加多信道&quot;">​</a></h3><p>转发是信道不是独立端口协议。主机密钥 TOFU 防中间人。TCP-over-TCP 当 VPN 有代价。Nagle 对按键有害。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：TCP 22 → KEX → 认证 → 信道。对照 HTTPS：证书 PKI vs known_hosts。与 keepalive：SSH 有应用层 ping。</p>',11)),(e(),n(h,null,{default:o(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCP%5B%22TCP%22%5D%20--%3E%20KEX%5B%22%E5%AF%86%E9%92%A5%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20KEX%20--%3E%20AUTH%5B%22%E7%94%A8%E6%88%B7%E8%AE%A4%E8%AF%81%22%5D%0A%20%20AUTH%20--%3E%20CH%5B%22%E5%A4%9A%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Nagle 对按键延迟有害，SSH 常关。窗口与流量控制在信道上。TSO 对小交互帮助有限。跳板与 ProxyJump 是会话层，不是 BGP。安全：认证失败限速，不写绕过。</p><p>SFTP 是子系统，不是另起 FTP 课的被动模式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SSH 证书 CA 的全部。NTP 是下一课。后课默认：SSH = 加密运输 + 认证 + 多信道。</p><p>把 SSH 当通用 VPN 要接受 TCP-over-TCP 的性能。</p><p>上一课留下的缺口在本课收口；「SSH 协议」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ntp">NTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一层加密运输，上面多信道。</li><li>主机密钥钉身份。</li><li>转发是信道，不是独立协议。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4253；RFC 4254。</li></ul>',10))])}const C=s(S,[["render",c]]);export{f as __pageData,C as default};
